-- ============================================================
-- TechNorte, Lda. — extração do sistema de gestão (ERP)
-- Base de dados operacional · MySQL 8 / MariaDB 10.6+
-- Período: 2024-01-01 a 2026-06-30
-- Importar:  mysql -u root -p < technorte_erp.sql
-- ============================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
DROP DATABASE IF EXISTS technorte_erp;
CREATE DATABASE technorte_erp CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE technorte_erp;

CREATE TABLE lojas (
  id INT PRIMARY KEY, nome VARCHAR(60) NOT NULL, cidade VARCHAR(40), distrito VARCHAR(40),
  regiao VARCHAR(20) NOT NULL, data_abertura DATE NOT NULL, area_m2 INT
);
CREATE TABLE categorias ( id INT PRIMARY KEY, nome VARCHAR(40) NOT NULL );
CREATE TABLE produtos (
  id INT PRIMARY KEY, codigo VARCHAR(10) NOT NULL UNIQUE, nome VARCHAR(80) NOT NULL,
  categoria_id INT NULL, marca VARCHAR(30), preco_venda DECIMAL(10,2) NOT NULL, ativo TINYINT NOT NULL DEFAULT 1,
  FOREIGN KEY (categoria_id) REFERENCES categorias(id)
);
CREATE TABLE clientes (
  id INT PRIMARY KEY, nome VARCHAR(80) NOT NULL, email VARCHAR(120), telefone VARCHAR(30),
  cidade VARCHAR(40), distrito VARCHAR(40), data_registo DATE, data_nascimento DATE NULL,
  genero CHAR(1), tipo VARCHAR(12), nif VARCHAR(12)
);
CREATE TABLE vendedores (
  id INT PRIMARY KEY, nome VARCHAR(80) NOT NULL, loja_id INT NOT NULL, data_admissao DATE, ativo TINYINT NOT NULL DEFAULT 1,
  FOREIGN KEY (loja_id) REFERENCES lojas(id)
);
CREATE TABLE encomendas (
  id INT PRIMARY KEY, data_hora DATETIME NOT NULL, cliente_id INT NOT NULL, loja_id INT NOT NULL,
  vendedor_id INT NULL, canal VARCHAR(10) NOT NULL, estado VARCHAR(12) NOT NULL,
  metodo_pagamento VARCHAR(15), campanha_id INT NULL,
  FOREIGN KEY (cliente_id) REFERENCES clientes(id), FOREIGN KEY (loja_id) REFERENCES lojas(id),
  FOREIGN KEY (vendedor_id) REFERENCES vendedores(id)
);
-- nota: linhas_encomenda.produto_id sem chave estrangeira (herdado do sistema antigo)
CREATE TABLE linhas_encomenda (
  id INT PRIMARY KEY, encomenda_id INT NOT NULL, produto_id INT NOT NULL,
  quantidade INT NOT NULL, preco_unitario DECIMAL(10,2) NOT NULL, desconto_pct DECIMAL(5,2) NOT NULL DEFAULT 0,
  FOREIGN KEY (encomenda_id) REFERENCES encomendas(id)
);
CREATE TABLE devolucoes (
  id INT PRIMARY KEY, encomenda_id INT NOT NULL, produto_id INT NOT NULL, data DATE NOT NULL,
  quantidade INT NOT NULL, motivo VARCHAR(40),
  FOREIGN KEY (encomenda_id) REFERENCES encomendas(id)
);

SET FOREIGN_KEY_CHECKS = 1;
